          key: { type: 'string' },
          value: { type: 'string' }
        },
        required: ['client_id', 'key', 'value'],
        additionalProperties: false
      }
    },
    {
      name: 'client_get',
      description: 'Read a value for a key from the given client\'s isolated map.',
      inputSchema: {
        type: 'object',
