          client_id: { type: 'string' },
          key: { type: 'string' }
        },
        required: ['client_id', 'key'],
        additionalProperties: false
      }
    }
  ];
}

export async function callTool(name, args = {}) {
  switch (name) {
    case 'open_client': {
      const { client_id } = args;
      assertNonEmptyString(client_id, 'client_id');
      if (!clients.has(client_id)) {
        clients.set(client_id, new Map());
      }
      return { content: [{ type: 'text', text: `client ${client_id} opened` }] };
    }
    case 'client_put': {
      const { client_id, key, value } = args;
      assertNonEmptyString(client_id, 'client_id');
      assertNonEmptyString(key, 'key');
      assertNonEmptyString(value, 'value');
      requireClient(client_id);
      clients.get(client_id).set(key, value);
      return { content: [{ type: 'text', text: `ok` }] };
    }
    case 'client_get': {
      const { client_id, key } = args;
      assertNonEmptyString(client_id, 'client_id');
      assertNonEmptyString(key, 'key');
      requireClient(client_id);
      const map = clients.get(client_id);
      if (!map.has(key)) {
        throw new Error(`unknown key: ${key}`);
      }
      return { content: [{ type: 'text', text: map.get(key) }] };
    }
    default:
      throw new Error(`unknown tool: ${name}`);
  }
}
